/**
 * The Material Symbols these screens draw, copied as path data so the module does not depend on
 * the extended icon library, which apps that do not shrink their builds would ship whole.
 * Icons are from Material Icons, Apache License 2.0.
 */
internal object ConsentIcons {
    private fun icon(mirror: Boolean, vararg paths: Triple<Float, Boolean, List<PathNode>>): ImageVector {
        val builder = ImageVector.Builder("inth", 24.dp, 24.dp, 24f, 24f, autoMirror = mirror)
        for ((alpha, evenOdd, data) in paths) builder.addPath(data, fill = SolidColor(Color.Black), fillAlpha = alpha,
            pathFillType = if (evenOdd) PathFillType.EvenOdd else PathFillType.NonZero)
        return builder.build()
    }

